#include <vector>
#include <algorithm>

class Solution {
public:
    long long minElevatorCost(std::vector<int>& requests, int capacity) {
        std::sort(requests.rbegin(), requests.rend());
        long long total = 0;
        for (size_t i = 0; i < requests.size(); i += capacity) {
            total += 2LL * requests[i];
        }
        return total;
    }
};

import java.util.*;

class Solution {
    public long minElevatorCost(int[] requests, int capacity) {
        Arrays.sort(requests);
        long total = 0;
        int n = requests.length;
        for (int i = n - 1; i >= 0; i -= capacity) {
            total += 2L * requests[i];
        }
        return total;
    }
}

